definition.raw:
\label{6.1.1}
The Gaussian binomial coefficients are defined by
\begin{equation}
\dbinom{n}{r}_q =
\begin{cases}
\frac{(1-q^n)(1-q^{n-1})\cdots(1-q^{n-r+1})}{(1-q)(1-q^2)\cdots(1-q^r)} & \text{if $r\le n$}\\
0 & \text{if $r > n$},
\end{cases}
\end{equation}
where  with $\mid q \mid < 1$ .

The beta function is defined as:
\begin{equation}
B(p,q) = \int_{0}^1 x^{p-1} (1-x)^{1-q}dx, \quad \textrm{for}\quad  Re(p), Re(q)>0.
\end{equation}
We have
\begin{equation}
B(p,q) =\frac{\Gamma (p) \Gamma (q)}{\Gamma{(p+q)}}.
\end{equation}

The incomplete beta function is defined as
\begin{equation}
B(x,p,q) = \int_{0}^x t^{p-1} (1-t)^{1-q}dt, \quad \textrm{for}\quad  Re(p), Re(q)>0.
\end{equation}

The regularized incomplete beta function is defined as
\begin{equation}
I_x(p,q) = \frac{B(x,p,q)}{B(p,q)}.
\end{equation}
In particular,  $I_x(p,1)=x^p$.

The upper and lower incomplete gamma functions are defined as
\begin{equation}
\Gamma(n,x) = \int_{x}^\infty  t^{n-1} e^{-t}dt\quad \textrm{and}
\end{equation}
\begin{equation}
\gamma(n,x) = \int_{0}^x  t^{n-1} e^{-t}dt \quad \textrm{respectively}.
\end{equation}

Kummer's confluent hyper-geometric functions $_{1}F_{1}(a;c;x)$ and  $U(a;c;x)$ are defined as below
\begin{equation}
_{1}F_{1}(a;c;x) = \sum_{n=0}^\infty \frac{(a)_n}{(c)_n} \frac{x^n}{n!},\quad c\ne 0,-1,-2,\cdots  \textrm{and} 
\end{equation}
\begin{equation}
U(a;c;x) = \frac{\pi}{\sin(\pi c)}\left(\frac{_{1}F_{1}(a;c;x)}{\Gamma(c)\Gamma(1+a-c)}-x^{1-c}\frac{_{1}F_{1}(1+a-c;2-c;x)}{\Gamma(a)\Gamma(2-c)}\right),
\end{equation}
\begin{equation}
-\pi<arg (x) \leq \pi.\nonumber
\end{equation}

\label{6.2.1}
The generalized Laguerre polynomials are defined as
\begin{eqnarray}
L_{n}^{(\alpha)}(x) &=& \sum_{m=0}^n (-1)^m \dbinom{n+\alpha}{n-m}\frac{x^m}{m!}\\
&=& \dbinom{n+\alpha}{n} {}_{1}F_{1}(-n;\alpha+1;x).
\end{eqnarray}

Let $f\in C_\alpha $ and $\alpha \geq -1$, then the (left-sided) Riemann-Liouville integral of order $\mu, \mu> 0 $ is given by
\begin{equation}
I^\mu f(t)=\frac{1}{\Gamma(\mu)} \int_{0}^t (t-\tau)^{\mu-1}f(\tau)d\tau,\quad t>0.
\end{equation}

The (left sided) Caputo fractional derivative of $f, f \in C_{-1}^m, m\in\mathbb{N}\cup\{0\}$, is defined as:
\begin{eqnarray}
D^\mu f(t)&=&\frac{d^m}{ dt^m} f(t),\quad \mu = m \nonumber\\
&=& I^{m-\mu}\frac{d^m}{ dt^m} f(t),\quad {m-1} <\mu <m,\quad m\in \mathbb{N}.
\end{eqnarray}

theorem.raw:
\cite{CONV}
If $N$ is $C^{(\infty)}$ in a neighborhood of $y_0$ and $\left\|N^{(n)}(y_0) \right\| \leq L$, for any $n$ and for some real $L>0$ and $\left\|y_i\right\| \leq M <\frac{1}{e}$, $i=1,2,\cdots,$ then the series $\sum_{n=0}^{\infty} G_n$ is absolutely convergent to $N$ and moreover,
\begin{equation*}
\left\|G_n\right\| \leq L M^n e^{n-1} (e-1), \quad n=1,2,\cdots.
\end{equation*}

(\textbf{Local existence})\label{th1}\\
Consider the equation
\begin{eqnarray}
y'(t)&=& f\left(t, y(t), y\left(t-\tau(t)\right)\right),\quad t_0 \leq t < t_f,\nonumber\\
y(t_0)&=& y_0,\label{pro1}
\end{eqnarray}
and assume that the function $f(t,u,v)$ is continuous on $A \subseteq [t_0,t_f)\times\mathbb{R}^m\times\mathbb{R}^m$ and locally Lipschitz continuous with respect to u and v. Moreover, assume that the delay function $\tau(t)\geq 0$ is continuous in $[t_0,t_f)$, $\tau(t_0)=0$ and, for some $\xi > 0 $, $t-\tau(t) > t_0$ in the interval $(t_0, t_0+\xi]$. Then the problem (\ref{pro1}) has a unique solution in $[t_0,t_0+\delta)$ for some $\delta >0$ and this solution depends continuously on the initial data.

If $0<q<1$, then the power series
\begin{equation}
 \mathcal{R}(a,b,q,x)=  1 + \sum_{n=1}^\infty \frac{x^n}{n!}\prod_{j=0}^{n-1}\left(a+bq^j\right)\label{6.5.0}
\end{equation}
 has infinite radius of convergence.

\label{6.1.3}
For $0<q<1$, $a \in \mathbb{R}$, $b \in \mathbb{R}$  and $m \in \mathbb{N} \cup\{0\} $, we have 
\begin{equation}
 \frac{d}{dx}\mathcal{R}(a,b,q,q^m x)=  a q^m \mathcal{R}(a,b,q,q^m x) + b q^m \mathcal{R}(a,b,q,q^{m+1}x).
\end{equation}

For $0<q<1$, $a \in \mathbb{R}$, $b \in \mathbb{R}$  and $m \in \mathbb{N}$, we have 
\begin{equation}
 \frac{d^m}{dx^m}\mathcal{R}(a,b,q,x)= \sum_{r=0}^m q^{\dbinom{r}{2}} \dbinom{m}{r}_q a^{m-r} b^r \mathcal{R}(a,b,q,q^r x),
\end{equation}
where $\dbinom{m}{r}_q$ is the Gaussian binomial coefficient.

For $0<q<1$, we have 
\begin{equation}
 \mathcal{R}(a, b, q, x) =  1 + \sum_{n=1}^\infty \sum_{r=0}^n q^{\dbinom{r}{2}}\dbinom{n}{r}_q a^{n-r}b^r \frac{x^n}{n!},
\end{equation}
where $\dbinom{n}{r}_q$ is the Gaussian binomial coefficient.

For $0<q<1$, $a\ge 0$ and  $b\ge 0$, the function $\mathcal{R}(a,b,q,x)$ satisfies the following inequality
\begin{equation}
 e^{ax}\le \mathcal{R}(a,b,q,x)\le e^{(a+b)x},\quad 0 \le x < \infty.
\end{equation}

\begin{eqnarray}
\int_{0}^xe^{-t}\mathcal{R}(a,b,q,t)dt &=& 1+ \sum_{n=1}^\infty  \sum_{r=0}^n q^{\dbinom{r}{2}} \dbinom{n}{r}_q a^{n-r} b^r \nonumber\\
&& -\Gamma (1, x)\left(1 + \sum_{n=1}^\infty \sum_{k=0}^n \sum_{r=0}^n q^{\dbinom{r}{2}} \dbinom{n}{r}_q a^{n-r} b^r  \frac{x^k}{k!}\right).
\end{eqnarray}

\begin{eqnarray}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt&=& \Gamma (1, x) + x\Gamma (1, x)\sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^{n-1}}{(n-1)!} U(1; 1+n; x)  \nonumber\\
&& + e^x\left(\mathcal{R}(a,b,q,x)-1\right).\\
&=&\Gamma (1, x) + \Gamma (1, x)\sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} U(1-n; 1-n; x)  \nonumber\\
&& + e^x\left(\mathcal{R}(a,b,q,x)-1\right).
\end{eqnarray}

If $0<q<1$, then the power series 

\begin{equation}
\mathcal{R}_\alpha(a, b, q, x) =1 + \sum_{n=1}^\infty \frac{x^{\alpha n}}{\Gamma{(\alpha n + 1)}}\prod_{j=0}^{n-1}\left(a+bq^{\alpha j}\right),\label{7.1.4}
\end{equation}
 is convergent for all finite values of $x$.

If $0<q<1$, and $(A+Bq^n)$ is invertible for each $n$, then the  power series 
\begin{equation}
\overline{\mathcal{R}}(A, B, q, xI) = \left( I  + \sum_{n=1}^\infty \frac{x^n}{n!}\prod_{j=1}^{n}\left(A+Bq^{n-j}\right)\right)Y_0,\label{7.2.4}
\end{equation}
where $A\in M_{n\times n}$ and $B\in M_{n\times n}$ is  convergent for $x\in\mathbb{R}$.

proof.raw:
Suppose
\begin{equation}
a_n =\frac{1}{n!}\prod_{j=0}^{n-1}\left(a+bq^j\right),\quad n=1,2,\cdots.
\end{equation}
If  $R$ is radius of convergence of (\ref{6.5.0}) then by using ratio test  \cite{Apostal}
\begin{eqnarray}
\frac{1}{R}=\lim_{n\to\infty}\left| \frac{a_{n+1}}{a_n}\right| &=&\lim_{n\to\infty}\left| \frac{ \frac{1}{{(n+1)!}}\prod_{j=0}^{n}\left(a+bq^j\right)}{ \frac{1}{n!}\prod_{j=0}^{n-1}\left(a+bq^j\right)}\right| \nonumber\\
&=& \lim_{n\to\infty} \left| \frac{a}{(n+1)} + \frac{bq^n}{(n+1)}\right| \nonumber\\
\Rightarrow\frac{1}{R}&=& 0 \quad (\because 0<q<1)\nonumber
\end{eqnarray}
Thus the series has infinite radius of convergence.

We have 
\begin{equation}
\mathcal{R}(a, b, q, x) =  1 + \sum_{n=1}^\infty \frac{x^n}{n!}\prod_{j=0}^{n-1}\left(a+bq^j\right).
\end{equation}
Using the $q$- binomial theorem 
\begin{equation}
\prod_{j=0}^{n-1}\left(a+bq^j\right) = \sum_{r=0}^n q^{\dbinom{r}{2}}\dbinom{n}{r}_q a^{n-r}b^r,\label{6.5.5} 
\end{equation}
defined in \cite{Richard}, we obtain
\begin{eqnarray}
\mathcal{R}(a, b, q, x) &=&  1 + \sum_{n=1}^\infty \frac{x^n}{n!}\sum_{r=0}^n q^{\dbinom{r}{2}}\dbinom{n}{r}_q a^{n-r}b^r\nonumber\\
\mathcal{R}(a, b, q, x) &=&   1 + \sum_{n=1}^\infty \sum_{r=0}^n q^{\dbinom{r}{2}}\dbinom{n}{r}_q a^{n-r}b^r \frac{x^n}{n!}.
\end{eqnarray}
Hence the proof.

Since $0<q<1$, $a\ge 0$, and  $b\ge 0$, we have
\begin{eqnarray}
\prod_{j=0}^{n-1}\left(a+bq^j\right) &\le& (a+b)^n \nonumber\\
\Rightarrow  \frac{x^n}{n!}\prod_{j=0}^{n-1}\left(a+bq^j\right) &\le&  \frac{x^n (a+b)^n}{n!}.\nonumber\\
\textrm{Taking summation over n, we get} \nonumber\\
 \mathcal{R}(a,b,q,x) &\le& e^{(a+b)x},\quad 0 \le x < \infty.\label{6.5.1}
\end{eqnarray}
Similarly, we have
\begin{eqnarray}
a^n &\le& \prod_{j=0}^{n-1}\left(a+bq^j\right)  \nonumber\\
\Rightarrow e^{ax} &\le& \mathcal{R}(a,b,q,x)  ,\quad 0 \le x < \infty.\label{6.5.2}
\end{eqnarray}
From (\ref{6.5.1}) and (\ref{6.5.2}), we get
\begin{equation}
 e^{ax}\le \mathcal{R}(a,b,q,x)\le e^{(a+b)x},\quad 0 \le x < \infty.
\end{equation}

Consider 
\begin{eqnarray}
\int_{0}^xe^{-t}\mathcal{R}(a,b,q,t)dt &=& \int_{0}^xe^{-t} + \sum_{n=1}^\infty  \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \int_{0}^xe^{-t}t^n dt\\
&=& 1- e^{-x} + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \gamma(n+1,x)\\
\end{eqnarray}
Using the property  (\ref{6.1.8}) in Section \textbf{\ref{6.1.4}}, we have
\begin{eqnarray}
&=& 1- e^{-x} + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \left(n\gamma(n,x)-x^n e^{-x}\right)\\
&=& 1- e^{-x}  + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} \left(\gamma(n,x)\right)-e^{-x}\sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^n}{n!}.
\end{eqnarray}
Using the relation (\ref{6.1.14}) in Section \textbf{\ref{6.1.4}}, we get
\begin{eqnarray}
 &=& 1 + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} \left( n^{-1} x^n e^{-x}{}_1F_{1}(1; n+1; x)\right) \nonumber\\
 &&-e^{-x}\mathcal{R}(a,b,q,x)\\
\int_{0}^xe^{-t}\mathcal{R}(a,b,q,t)dt&=& 1 + \Gamma (1, x)\left(\sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^n}{n!} {}_1F_{1}(1; n+1; x) - \mathcal{R}(a,b,q,x)\right)\nonumber
\end{eqnarray}
Again using the relation (\ref{6.1.15}) in \textbf{\ref{6.1.4}}, we get
\begin{equation}
 \int_{0}^xe^{-t}\mathcal{R}(a,b,q,t)dt= 1 -\Gamma (1, x) \mathcal{R}(a,b,q,x) + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^n}{n!} {}_1F_{1}(n; n+1; -x)  \nonumber
\end{equation}

Consider 
\begin{eqnarray*}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt &=& \int_{x}^\infty e^{-t} + \sum_{n=1}^\infty  \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \int_{x}^\infty e^{-t}t^n dt\\
&=& e^{-x} + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \Gamma(n+1,x)\\
\end{eqnarray*}
Using the properties (\ref{6.1.5}) and (\ref{6.1.7}) in Section \textbf{\ref{6.1.4}}, we have
\begin{eqnarray*}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt &=& \Gamma (1, x) + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{n!} \left(n\Gamma(n,x)+x^n e^x\right)\\
&=& \Gamma (1, x) + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} \left(\Gamma(n,x)\right)+e^x\sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^n}{n!}.
\end{eqnarray*}
Using the relation (\ref{6.1.16}), we get
\begin{eqnarray*}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt &=& \Gamma (1, x) + \sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} \left( x^n e^{-x}U(1; 1+n; x)\right) \nonumber\\ 
&& + e^x\left(\mathcal{R}(a,b,q,x)-1\right)\\
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt&=& \Gamma (1, x) + x\Gamma (1, x)\sum_{n=1}^\infty \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {x^{n-1}}{(n-1)!} U(1; 1+n; x)  \nonumber\\
&& + e^x\left(\mathcal{R}(a,b,q,x)-1\right).
\end{eqnarray*}
Again using the relation (\ref{6.1.17}), we get
\begin{eqnarray}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,t)dt&=& \Gamma (1, x) + \Gamma (1, x)\sum_{n=1}^\infty \prod_{j=0}^{n-1}\frac {\left(a+bq^j\right)}{(n-1)!} U(1-n; 1-n; x)  \nonumber\\
&& + e^x\left(\mathcal{R}(a,b,q,x)-1\right).
\end{eqnarray}

We have 
\begin{eqnarray}
\int_{0}^x e^{-t}\mathcal{R}(a,b,q,\lambda t)dt &=& 1 - e^{-x} +  
\sum_{n=1}^\infty  \prod_{j=0}^{n-1}\frac{\left(a+bq^j\right)}{n!}\int_{0}^x e^{-t}(\lambda t)^n dt\nonumber\\
&=& \gamma(1,x) + \sum_{n=1}^\infty  \prod_{j=0}^{n-1} \frac {\left(a+bq^j\right)}{n!} \gamma(n+1,\lambda x). 
\end{eqnarray}
By using the property \cite{Gautschi}
 $\gamma(n,\lambda x) = \lambda^n\sum_{m=0}^n\frac{\gamma(n+m, x)}{m!}(1-\lambda)^m$, we get 
\begin{equation*}
\int_{0}^x e^{-t}\mathcal{R}(a,b,q,\lambda t)dt = \gamma (1, x) + 
\lambda\sum_{n=1}^\infty \sum_{m=0}^{n+1} \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {\lambda^n}{n!} \frac {\gamma(n+m+1, x)}{m!}(1-\lambda)^m.
\end{equation*}

\begin{eqnarray}
\int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,\lambda t)dt &=& e^{-x} +  
\sum_{n=1}^\infty  \prod_{j=0}^{n-1}\frac{\left(a+bq^j\right)}{n!}\int_{x}^\infty e^{-t}(\lambda t)^n dt\nonumber\\
&=& \Gamma(1,x) + \sum_{n=1}^\infty  \prod_{j=0}^{n-1} \frac {\left(a+bq^j\right)}{n!} \Gamma(n+1,\lambda x). 
\end{eqnarray}
By using the property \cite{Gautschi}
 $\Gamma(n,\lambda x) = \lambda^n\sum_{m=0}^n\frac{\Gamma(n+m, x)}{m!}(1-\lambda)^m$, we obtain
 \begin{equation*}
 \int_{x}^\infty e^{-t}\mathcal{R}(a,b,q,\lambda t)dt = \Gamma (1, x) + 
 \lambda \sum_{n=1}^\infty \sum_{m=0}^{n+1} \prod_{j=0}^{n-1}\left(a+bq^j\right)\frac {\lambda^n}{n!} \frac {\Gamma(n+m+1, x)}{m!}(1-\lambda)^m.
 \end{equation*}

Result follows immediately by ratio test 

\begin{eqnarray*}
\lim_{n\to\infty}\left| \frac{a_{n+1}}{a_n}\right| &=& a \left|x\right|^\alpha \lim_{n\to\infty}\frac {\Gamma(\alpha n)}{\Gamma{(\alpha (n + 1))}}\\
&=& 0.
\end{eqnarray*}

