\begin{The}\label{6.1.3}
For $0<q<1$, $a \in \mathbb{R}$, $b \in \mathbb{R}$  and $m \in \mathbb{N} \cup\{0\} $, we have 
\begin{equation}
 \frac{d}{dx}\mathcal{R}(a,b,q,q^m x)=  a q^m \mathcal{R}(a,b,q,q^m x) + b q^m \mathcal{R}(a,b,q,q^{m+1}x).
\end{equation}
\end{The}

\begin{proof}

Consider
\begin{eqnarray*}
\frac{d}{dx}\mathcal{R}(a,b,q,q^m x) &=& \frac{d}{dx} \left( 1 + \sum_{n=1}^\infty\frac{(q^m x)^n}{n!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\right)\\ 
&=& q^m\sum_{n=1}^\infty\frac{(q^m x)^{n-1}}{(n-1)!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=2}^\infty\frac{(q^m x)^{n-1}}{(n-1)!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=1}^\infty\frac{(q^m x)^{n}}{{n}!}\prod_{j=0}^{n}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=1}^\infty\frac{(q^m x)^{n}(a+bq^n)}{{n}!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& aq^m  \left( 1 + \sum_{n=1}^\infty\frac{(q^m x)^n}{n!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\right)\\
&& + bq^m  \left( 1 + \sum_{n=1}^\infty\frac{(q^{m+1}x)^n}{n!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\right)\\
 \frac{d}{dx}\mathcal{R}(a,b,q,q^m x) &=&  a q^m \mathcal{R}(a,b,q,q^m x) + b q^m \mathcal{R}(a,b,q,q^{m+1}x)
\end{eqnarray*}
Hence the proof.
\end{proof}



\begin{The}
For $0<q<1$, $a \in \mathbb{R}$, $b \in \mathbb{R}$  and $m \in \mathbb{N}$, we have 
\begin{equation}
 \frac{d^m}{dx^m}\mathcal{R}(a,b,q,x)= \sum_{r=0}^m q^{\dbinom{r}{2}} \dbinom{m}{r}_q a^{m-r} b^r \mathcal{R}(a,b,q,q^r x),
\end{equation}
where $\dbinom{m}{r}_q$ is the Gaussian binomial coefficient.
\end{The}

\begin{proof}
We prove the result by induction hypothesis on $m$.\\

From Theorem \ref{6.1.3}, the result is true for $m=1$. \\
Suppose, 
\begin{equation}
 \frac{d^{m-1}}{dx^{m-1}}\mathcal{R}(a,b,q,x)= \sum_{r=0}^{m-1} q^{\dbinom{r}{2}}\dbinom{m-1}{r}_q a^{m-(r+1)} b^r \mathcal{R}(a,b,q,q^r x).
\end{equation}
Consider,\\
\begin{eqnarray}
\frac{d^m}{dx^m}\mathcal{R}(a,b,q,x) &=& \frac{d}{dx} \left(\frac{d^{m-1}}{dx^{m-1}}\mathcal{R}(a,b,q,x)\right)\\
&=& \frac{d}{dx} \left( \sum_{r=0}^{m-1} q^{\dbinom{r}{2}} \dbinom{m-1}{r}_q a^{m-(r+1)} b^r \mathcal{R}(a,b,q,q^r x)\right)\\
&=& \sum_{r=0}^{m-1} q^{\dbinom{r}{2}} \dbinom{m-1}{r}_q a^{m-(r+1)} b^r \frac{d}{dx}\mathcal{R}(a,b,q,q^r x).
\end{eqnarray}
Using Theorem [\ref{6.1.3}], we have
\begin{eqnarray*}
\frac{d^m}{dx^m}\mathcal{R}(a,b,q,x) &=& \sum_{r=0}^{m-1} q^{\dbinom{r}{2}} \dbinom{m-1}{r}_q a^{m-(r+1)} b^r \nonumber\\
&&\left( a q^r \mathcal{R}(a,b,q,q^rx) + b q^r \mathcal{R}(a,b,q,q^{r+1}x)\right)\\
&=& \sum_{r=0}^{m-1} q^{\dbinom{r}{2}}  q^r  \dbinom{m-1}{r}_q a^{m-r} b^r  \mathcal{R}(a,b,q,q^rx)\\
&&+ \sum_{k=0}^{m-1} q^{\dbinom{k}{2}}  q^k  \dbinom{m-1}{k}_q a^{m-(k+1)} b^{k+1} \mathcal{R}(a,b,q,q^{k+1}x)
\end{eqnarray*}
\begin{eqnarray*}
&=& \sum_{r=0}^{m-1} q^{\dbinom{r}{2}} q^r \dbinom{m-1}{r}_q  a^{m-r} b^r  \mathcal{R}(a,b,q,q^rx)\\
&& + \sum_{k=1}^{m} q^{\dbinom{k}{2}} \dbinom{m-1}{k-1}_q a^{m-k} b^k  \mathcal{R}(a,b,q,q^kx)\\
&=& \sum_{r=0}^{m} q^{\dbinom{r}{2}} q^r \dbinom{m-1}{r}_q  a^{m-r} b^r  \mathcal{R}(a,b,q,q^rx)\nonumber\\
&& - q^{\dbinom{m}{2}} q^m  \dbinom{m-1}{m}_q b^m  \mathcal{R}(a,b,q,q^m x) \\
&& + \sum_{k=0}^{m} q^{\dbinom{k}{2}} \dbinom{m-1}{k-1}_q a^{m-k} b^k \mathcal{R}(a,b,q,q^kx) \nonumber\\
&& -  \dbinom{m-1}{-1}_q a^m  \mathcal{R}(a,b,q, x) \\
&=& \sum_{r=0}^{m} q^{\dbinom{r}{2}} q^r \dbinom{m-1}{r}_q  a^{m-r} b^r  \mathcal{R}(a,b,q,q^rx)\\
&& + \sum_{k=0}^{m} q^{\dbinom{k}{2}} \dbinom{m-1}{k-1}_q a^{m-k} b^k q^r \mathcal{R}(a,b,q,q^kx) \\
&=& \sum_{r=0}^{m} q^{\dbinom{r}{2}} \left(q^r \dbinom{m-1}{r}_q + \dbinom{m-1}{r-1}_q \right) a^{m-r} b^r  \mathcal{R}(a,b,q,q^rx).
\end{eqnarray*}
Using identity (\ref{6.1.2}),
\begin{equation}
 \frac{d^m}{dx^m}\mathcal{R}(a,b,q,x)= \sum_{r=0}^m q^{\dbinom{r}{2}} \dbinom{m}{r}_q a^{m-r} b^r \mathcal{R}(a,b,q,q^rx),
\end{equation}
This completes the proof.
