&=& q^m\sum_{n=1}^\infty\frac{(q^m x)^{n-1}}{(n-1)!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=2}^\infty\frac{(q^m x)^{n-1}}{(n-1)!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=1}^\infty\frac{(q^m x)^{n}}{{n}!}\prod_{j=0}^{n}\left(a + bq^j\right)\\
&=& q^m (a+b) + q^m\sum_{n=1}^\infty\frac{(q^m x)^{n}(a+bq^n)}{{n}!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\\
&=& aq^m  \left( 1 + \sum_{n=1}^\infty\frac{(q^m x)^n}{n!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\right)\\
&& + bq^m  \left( 1 + \sum_{n=1}^\infty\frac{(q^{m+1}x)^n}{n!}\prod_{j=0}^{n-1}\left(a + bq^j\right)\right)\\
 \frac{d}{dx}\mathcal{R}(a,b,q,q^m x) &=&  a q^m \mathcal{R}(a,b,q,q^m x) + b q^m \mathcal{R}(a,b,q,q^{m+1}x)
\end{eqnarray*}
Hence the proof.
\end{proof}



